import { MAX_PIECES } from './core/pieces.js';
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const displayNumber=value=>Number(Number(value).toFixed(2));

function pieceRows(chart){const groups=[];for(const row of chart.rowCounts){const key=JSON.stringify(row.segments),last=groups.at(-1);if(last?.key===key)last.end=row.row;else groups.push({start:row.row,end:row.row,key,count:row.count,segments:row.segments.length});}return `<details class="piece-row-details"><summary>逐行针数</summary><div class="row-summary"><table><thead><tr><th>行号</th><th>有效针数</th></tr></thead><tbody>${groups.map(r=>`<tr><td>${r.start===r.end?r.start:r.start+'–'+r.end} 行</td><td>${r.count} 针${r.segments>1?' · 分'+r.segments+'段':''}</td></tr>`).join('')}</tbody></table></div></details>`;}

export function pieceSelectorHTML(entries,activeId){return `<section class="section piece-selector"><h3 class="section-title">本工程裁片<span class="muted">${entries.length} / ${MAX_PIECES} 片</span></h3><div class="piece-selector-buttons">${entries.map(e=>`<button class="btn small ${e.id===activeId?'soft selected':''}" data-edit-piece="${esc(e.id)}" aria-pressed="${e.id===activeId}">${esc(e.label)}</button>`).join('')}</div><button class="btn full soft add-piece-button" data-action="add-piece" ${entries.length>=MAX_PIECES?'disabled':''}>＋ 添加裁片</button><div class="piece-manage-actions"><button class="btn text small" data-action="rename-piece">重命名</button><button class="btn text small" data-action="duplicate-piece" ${entries.length>=MAX_PIECES?'disabled':''}>复制裁片</button><button class="btn text small danger" data-action="remove-piece" ${entries.length===1?'disabled':''}>移除裁片</button></div><p class="hint">正在编辑：${esc(entries.find(e=>e.id===activeId)?.label||'当前裁片')}。可组合前片、后片、袖子等，各片尺寸、提花和针法独立保存。</p></section>`;}

export function pieceBoardHTML(entries,activeId,kind,renderShape){return `<div class="piece-board ${entries.length===3?'three-pieces':''} ${entries.length>3?'many-pieces':''} ${entries.length===1?'one-piece':''}">${entries.map(e=>`<article class="piece-card ${e.id===activeId?'active':''}" data-piece-card="${esc(e.id)}" aria-label="${esc(e.label)}${kind==='shape'?'版型':'编织图解'}"><header class="piece-card-header"><div><h3>${esc(e.label)}</h3><p>${displayNumber(e.project.measurements.width)} × ${displayNumber(e.project.measurements.height)} cm · ${e.chart.stitches} 针 × ${e.chart.rows} 行</p></div><button class="btn small ${e.id===activeId?'soft':''}" data-edit-piece="${esc(e.id)}" aria-label="编辑${esc(e.label)}">${e.id===activeId?'正在编辑':'编辑'+esc(e.label)}</button></header>${kind==='shape'?`<div class="piece-shape-stage">${renderShape(e)}</div>`:`<div class="piece-grid-stage"><canvas ${e.id===activeId?'id="grid-canvas"':`data-preview-piece="${esc(e.id)}"`} aria-label="${esc(e.label)}提花网格" role="img"></canvas></div>`}<div class="piece-card-footer">${e.project.outlineDrawing?'<div class="draft-piece-badge">有绘制草稿 · 应用后更新图解</div>':''}${kind==='chart'?pieceRows(e.chart):''}${e.id===activeId?(kind==='shape'?'点击尺寸可修改 · 文字可拖动编辑':'绘制颜色与针法 · 选择提花后可移动位置'):`点击「编辑${esc(e.label)}」调整此片，其他裁片仍会保留在页面上。`}</div></article>`).join('')}</div>`;}
